from __future__ import annotations

import json

import pytest

from llm_router import LLMRouter, Model, Provider, RouterProfile
from tests.llm_router.support.fault_server import (
    ScriptedHTTPServer,
    ScriptedResponse,
)
from tests.llm_router.support.workers.retry import (
    openai_chat_path,
    openai_success_response,
)
from tests.llm_router.support.workers.worker_patches import prepare_fault_case

pytestmark = pytest.mark.verification_kind("unit")


@pytest.mark.verifies("REQ_STRUCTURED_SCHEMA_CONTRACT[revision==2]")
def test_aistudio_schema_transform_keeps_caller_schema_name() -> None:
    path = openai_chat_path()
    schema = {
        "title": "invoice_totals",
        "type": "object",
        "$defs": {"amount": {"type": "integer", "minimum": 1}},
        "properties": {"total_cents": {"$ref": "#/$defs/amount"}},
        "required": ["total_cents"],
    }
    with ScriptedHTTPServer(
        port=0,
        routes={
            ("POST", path): [
                ScriptedResponse(
                    status_code=200,
                    headers={"Content-Type": "application/json"},
                    body=openai_success_response(text='{"total_cents": 1250}'),
                )
            ]
        },
    ) as server:
        prepare_fault_case(case="aistudio_video", server_base_url=server.base_url)
        router = LLMRouter(
            RouterProfile(model=Model.GEMINI_FLASH, provider=Provider.AISTUDIO)
        )

        response = router.query("Total the invoice.", response_schema=schema)

        request_record = next(iter(server.recorded_requests("POST", path)))
        body = json.loads(request_record.body)

    json_schema = body["response_format"]["json_schema"]
    assert json_schema["name"] == "invoice_totals"
    assert json_schema["schema"]["required"] == ["total_cents"]
    assert json.loads(response.output_text) == {"total_cents": 1250}
